"""Wrapper around a bundled MediaMTX binary providing a local RTMP ingest."""

from __future__ import annotations

import logging
import socket
import subprocess
import sys
from pathlib import Path

from .config import default_data_dir
from .resources import resource_path

log = logging.getLogger("hiveshot.ingest")

MEDIAMTX_YML = """\
# Generated by HiveShotTracker: RTMP only.
logLevel: info
rtsp: no
webrtc: no
hls: no
srt: no
api: no
metrics: no
pprof: no
playback: no
rtmp: yes
rtmpAddress: :{port}
paths:
  all_others:
"""


class RtmpServerError(RuntimeError):
    pass


class RtmpServer:
    def __init__(self, binary: Path | None = None,
                 data_dir: Path | None = None, port: int = 1935,
                 kill_adopted: bool = False):
        self.binary = Path(binary) if binary else resource_path("bin") / "mediamtx.exe"
        self.data_dir = Path(data_dir) if data_dir else default_data_dir()
        self.port = port
        self._proc: subprocess.Popen | None = None
        self.kill_adopted = kill_adopted
        self.adopted = False
        self._adopted_pids: list[int] = []

    @property
    def config_path(self) -> Path:
        return self.data_dir / "mediamtx.yml"

    def is_available(self) -> bool:
        return self.binary.is_file()

    def url_for(self, stream_name: str) -> str:
        return f"rtmp://127.0.0.1:{self.port}/{stream_name}"

    def write_config(self) -> Path:
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.config_path.write_text(
            MEDIAMTX_YML.format(port=self.port), encoding="utf-8")
        return self.config_path

    def is_running(self) -> bool:
        if self._proc is not None and self._proc.poll() is None:
            return True
        return self.adopted and self._port_busy()

    def _port_busy(self) -> bool:
        try:
            with socket.create_connection(("127.0.0.1", self.port), timeout=0.3):
                return True
        except OSError:
            return False

    def _mediamtx_pids(self) -> list[int]:
        """PIDs of running mediamtx.exe processes (tasklist; no psutil)."""
        if sys.platform != "win32":
            return []
        try:
            out = subprocess.run(
                ["tasklist", "/FI", "IMAGENAME eq mediamtx.exe", "/FO", "CSV", "/NH"],
                capture_output=True, text=True, timeout=10, check=False).stdout
        except (OSError, subprocess.SubprocessError):
            return []
        pids = []
        for line in out.splitlines():
            parts = [x.strip('"') for x in line.strip().split('","')]
            if len(parts) >= 2 and parts[0].strip('"').lower() == "mediamtx.exe":
                try:
                    pids.append(int(parts[1].strip('"')))
                except ValueError:
                    pass
        return pids

    def start(self) -> None:
        if not self.is_available():
            raise RtmpServerError(
                f"MediaMTX binary not found at {self.binary}. Download the "
                "Windows release of MediaMTX (github.com/bluenviron/mediamtx) "
                "and place mediamtx.exe in the bin/ folder, then retry."
            )
        if self.is_running():
            return
        if self._port_busy():
            pids = self._mediamtx_pids()
            if pids:
                self.adopted = True
                self._adopted_pids = pids
                log.warning("port %d already served by mediamtx.exe (pids %s), "
                            "probably orphaned from a previous run; adopting it",
                            self.port, pids)
                return
            raise RtmpServerError(
                f"RTMP port {self.port} busy by another process (not mediamtx.exe). "
                "Close the program using it or choose another port.")
        cfg = self.write_config()
        self._proc = subprocess.Popen(
            [str(self.binary), str(cfg)],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        log.info("started MediaMTX pid %s on port %d", self._proc.pid, self.port)

    def stop(self) -> None:
        p = self._proc
        self._proc = None
        if self.adopted:
            pids, self._adopted_pids, self.adopted = self._adopted_pids, [], False
            if self.kill_adopted:
                for pid in pids:
                    subprocess.run(["taskkill", "/PID", str(pid), "/F"],
                                   capture_output=True, check=False, timeout=10)
            return
        if p is None:
            return
        p.terminate()
        try:
            p.wait(timeout=3)
        except subprocess.TimeoutExpired:
            p.kill()
            p.wait(timeout=3)
